 "content": "def transform(grid):
    out = [row[:] for row in grid]
    height = len(out)
    if height == 0:
        return out
    width = len(out[0])
    # A 5 in the bottom row marks a vertical column to complete.
    for c in range(width):
        if out[height - 1][c] != 5:
            continue
        anchors = [r for r in range(height) if out[r][c] != 0]
        for r in range(height):
            if out[r][c] != 0:
                continue
            below = [a for a in anchors if a >= r]
            anchor = min(below) if below else max(anchors)
            out[r][c] = out[anchor][c]
    return out
